def countMazeRoutes(maze):
    m, n = len(maze), len(maze[0])
    w = n + 2                       # one extra column of walls on each side, and rows above and below
    blocked = [True] * ((m + 2) * w)
    for r in range(m):
        for c in range(n):
            blocked[(r + 1) * w + c + 1] = maze[r][c] == 1
    start, target = w + 1, m * w + n
    steps = (w, -w, 1, -1)

    def go(cell):
        if cell == target:
            return 1
        blocked[cell] = True        # visited cells behave like walls
        total = 0
        for d in steps:
            nxt = cell + d
            if not blocked[nxt]:
                total += go(nxt)
        blocked[cell] = False
        return total

    return go(start)
